contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address to,
        uint256 baseIn,
        uint256 quoteIn
    ) public {
        require(to != address(0), "to zero");
        require(baseIn > 0, "no base input");

        // The test contract must be able to transfer the input tokens into c.
        // These tokens are assumed to be available to this test contract; if not,
        // the buyShares call will revert and the assertion below simply will not
        // be reached.  The property characterizes successful buys.
        address baseToken = address(c._BASE_TOKEN_());
        address quoteToken = address(c._QUOTE_TOKEN_());

        // Move the caller's tokens into c before calling buyShares.
        (bool okBase, ) = baseToken.call(
            abi.encodeWithSignature("transfer(address,uint256)", address(c), baseIn)
        );
        require(okBase, "base transfer failed");

        if (quoteIn > 0) {
            (bool okQuote, ) = quoteToken.call(
                abi.encodeWithSignature("transfer(address,uint256)", address(c), quoteIn)
            );
            require(okQuote, "quote transfer failed");
        }

        uint256 supplyBefore = c.totalSupply();
        uint256 sharesBefore = c.balanceOf(to);

        (uint256 shares, uint256 baseInput, uint256 quoteInput) = c.buyShares(to);

        uint256 supplyAfter = c.totalSupply();
        uint256 sharesAfter = c.balanceOf(to);

        // Rule: a successful buyShares mints shares to `to`, so the recipient's
        // balance and the total supply both grow by exactly the returned amount.
        assert(
            shares > 0 &&
            sharesAfter == sharesBefore + shares &&
            supplyAfter == supplyBefore + shares
        );
    }

    receive() external payable {}
}

